/*
 * Solder: BreezeMate Desk Fan (Draft with Seed Pin Conflict)
 * Target: Arduino Uno (ATmega328P)
 */
#include <Wire.h>

#define DHT_PIN 4
#define RELAY_PIN 7
#define FAN_PIN 7 // Initial intentional pin collision on D7!

void setup() {
  Serial.begin(9600);
  pinMode(DHT_PIN, INPUT);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, HIGH); // Relay off on boot
  Serial.println(F("SYSTEM_BOOT: OK"));
}

void loop() {
  Serial.println(F("FAN:ACTIVE"));
  delay(1000);
}
